mapper.select:
select
seat.*,
studyhall.name
from seat seat
left join studyhall studyhall on seat.hall_id = studyhall.id

    and seat.id = #{id}
    and seat.number = #{number}
    and seat.hall_id = #{hallId}
    and seat.qr_code = #{qrCode}
    and seat.status = #{status}
    and seat.create_time = #{createTime}
    and studyhall.name like concat('%',#{name},'%')


    limit #{current},#{pageSize}

select count(*) from seat seat
left join studyhall studyhall on seat.hall_id = studyhall.id

    and seat.id = #{id}
    and seat.number = #{number}
    and seat.hall_id = #{hallId}
    and seat.qr_code = #{qrCode}
    and seat.status = #{status}
    and seat.create_time = #{createTime}
    and studyhall.name like concat('%',#{name},'%')
